sqlMap.insert:
INSERT INTO PA_BENHS_BENCHMARK ( PA_BENHS_BENCH_SEQ, INSURANCE_CODE, REG_TYPE_CODE, UPPER_LIMIT, LOWER_LIMIT, COR_RATE, PER_RATE, COR_VALUE, PER_VALUE, CREATE_DATE, CREATED_BY, ACTIVITY
)VALUES( PA_BENHS_BENCH_SEQ.NEXTVAL, #insturanceCode:VARCHAR#, #regTypeCode:VARCHAR#, #upperLimit#, #lowerLimit#, #corRate#, #perRate#, #corValue#, #perValue#, SYSDATE, #adminID#, 1
)

INSERT INTO PA_BENHS_BASE (PA_BENHS_BASE_SEQ, PERSON_ID, SOCIAL_NO, AVG_SALARY, PAY_SALARY, SOCIAL_STATUS, IMP_TYPE, CREATE_DATE, CREATED_BY, ACTIVITY) (SELECT PA_BENHS_BASE_SEQ.NEXTVAL, T.PERSON_ID, T.SOCIAL_NO, T.AVG_SALARY, T.AVG_SALARY, T.SOCIAL_STATUS, 'N', SYSDATE, #adminID#, 1 FROM PA_BENHS_MANAGE T,HR_EMPLOYEE E WHERE TO_CHAR(T.CREATE_DATE, 'yyyymm') = #pabDate# AND T.PERSON_ID = E.PERSON_ID AND T.PERSON_ID NOT IN(SELECT PERSON_ID FROM PA_BENHS_BASE B)
(E.DATE_LEFT IS NULL OR (E.DATE_LEFT IS NOT NULL AND E.DATE_LEFT >= TO_DATE(#leftDate:DATE#,'YYYY-MM-DD')))
)
